// Register 30845-30852: Bat.ChaStt (SoC, U32 %), 30847 kapacitet, 30849 temperatur, 30851 Bat.Vol (U32, 0,01 V)
// Skriver global "sma": batSoc, batVol  (varje nyckel = {v, ts})
const p = msg.payload;
if (!Array.isArray(p) || p.length < 8) {
    node.status({fill: "red", shape: "ring", text: "Väntar på 8 register"});
    return null;
}
const u32 = (h, l) => ((h << 16) | l) >>> 0;
const NAN_U32 = 0xFFFFFFFF;
const soc = u32(p[0], p[1]);
const volRaw = u32(p[6], p[7]);
const s = global.get("sma") || {};
const ts = Date.now();
const txt = [];
const socOk = soc !== NAN_U32 && soc <= 100; // ogiltig SoC uppdaterar inte -> värdet blir gammalt -> FAILSAFE
if (socOk) { s.batSoc = {v: soc, ts}; txt.push("SoC: " + soc + " %"); } else { txt.push("SoC ogiltig"); }
if (volRaw !== NAN_U32) { s.batVol = {v: volRaw / 100, ts}; txt.push("Bat.Vol: " + (volRaw / 100) + " V"); }
global.set("sma", s);
node.status({fill: socOk ? "green" : "yellow", shape: "dot", text: txt.join(" | ")});
msg.payload = {soc: socOk ? soc : null, vol_v: volRaw === NAN_U32 ? null : volRaw / 100};
return msg;

const v = msg.payload;
global.set("sma_soc", v);
node.status({fill: "blue", shape: "dot", text: `Mål-SoC: ${v} %`});
return null;

// SMA Control v2 - ersätter "SMA Control" i produktionsfliken.
// Utgång 1: Modbus-/MQTT-meddelanden (address + payload) -> switch -> modbus-write/mqtt out.
// Utgång 2: debug-plan (visas när något skickas).
// Mätvärden ligger i globalen "sma" = { nyckel: {v, ts} }, skrivs av avkodarna. Gamla värden (> MAX_AGE_MS) -> FAILSAFE för de obligatoriska:
//   batSoc (30845), grid (30865/30867, + import), pvA (30773), pvB (30961), invAc (30775).  Valfria: batChg/batDsch/batNet (31393/31395), phaseMax (31435), batVol (30851).
// MQTT-inställningar (globaler): sma_soc (mål-SoC), zero_export, discharge, charge_power, peak.

// ---------- Konstanter (justera här) ----------
const INV_MAX_W = 8000;          // STP 8.0 SE: märkeffekt / max skenbar AC-effekt (8000 W / 8000 VA, 3 x 12,1 A max)
const BAT_MAX_CHARGE_W = 10600;    // STP 8.0 SE: max batteriladdning (DC-sidan)
const BAT_MAX_DISCHARGE_W = 10600; // STP 8.0 SE: max batteriurladdning (DC-sidan); AC-utgången begränsar till INV_MAX_W
const GRID_MAX_W = 13000;        // max total nätimport = standard-peak när MQTT sma/peak är 0/osatt
const CHARGE_MAX_W = 9000;       // max laddeffekt (ditt tak, som i produktion; databladet tillåter BAT_MAX_CHARGE_W)
const DISCHARGE_MIN_W = 2500;    // discharge under detta = 0 (som produktion)
const PHASE_LIMIT_A = 20;        // huvudsäkring per fas (20 A, bekräftat)
const PHASE_MARGIN_A = 1;        // marginal under säkringen
const GRID_VOLT = 230;           // fasspänning
const MAX_AGE_MS = 10000;        // äldre än detta = gammalt värde -> FAILSAFE (gäller t_*-registren)
const SOC_HYST = 1;              // CHARGE startar när SoC < mål - SOC_HYST (0 = så fort SoC är under målet), fortsätter till SoC >= mål
const PHASE_GAIN = 0.10;         // fas-peak: integrerande reglering, börvärde = förra börvärdet + PHASE_GAIN * (uppmätt maxfas - trigger) * 690 W/A
const PHASE_KICK = 0.5;          // vid start av fas-peak: direkt kliv på PHASE_KICK * (fel i A) * 690 W
const PHASE_MAX_LEAD_W = 800;    // anti-windup: börvärdet får ligga högst så här mycket över uppmätt urladdning
const PHASE_CHG_GAIN_DOWN = 0.3; // laddning: när fasen är över gränsen minskas laddgränsen med PHASE_CHG_GAIN_DOWN * överskott(A) * 690 W per tick
const PHASE_CHG_GAIN_UP = 0.1;   // laddning: när det finns marginal höjs laddgränsen långsammare (PHASE_CHG_GAIN_UP)
const PHASE_CHG_MAX_LEAD_W = 1000; // anti-windup: laddgränsen får ligga högst så här mycket över uppmätt laddning
const PHASE_RELEASE_W = 20;      // fas-peak släpper när behovet <= detta
const PHASE_CONFIRM_N = 3;       // fas-peak startar först när startvillkoret gällt så här många körningar i följd (filtrerar enstaka felläsningar/spikar)
const PHASE_CONFIRM_MS = 1900;   // ...och minst så här länge (3 läsningar med 1 s mellanrum), ifall funktionen körs oftare än en gång per sekund
const PEAK_MIN_SOC = 5;          // effekt-peak (sma/peak, reserv 13 kW) startar inte under denna SoC. Fas-peak (säkringen) påverkas inte
const PEAK_MIN_SOC_HYST = 2;     // effekt-peak får tillbaka först vid SoC >= PEAK_MIN_SOC + detta
const PEAK_GAIN = 0.15;          // effekt-peak: integrerande reglering, börvärde = förra börvärdet + PEAK_GAIN * (uppmätt nätimport - peak)
const PEAK_MAX_LEAD_W = 800;     // anti-windup: börvärdet får ligga högst så här mycket över uppmätt urladdning
const PEAK_RELEASE_W = 20;       // effekt-peak släpper när behovet <= detta
const PEAK_HYST_W = 200;         // reserv (saknad batteridata): PEAK_SHAVING släpper först när import < peak - PEAK_HYST_W
const MIN_DWELL_MS = 20000;      // minsta tid i ett läge (PEAK_SHAVING och FAILSAFE undantagna)
const AUTO_ENTER_MS = 10000;     // LOCKED -> AUTO först när solöverskott (sol > hus + 50 W) funnits så här länge i sträck
const AUTO_HOLD_MS = 60000;      // AUTO -> LOCKED (vid SoC = mål) först när solöverskott saknats så här länge
const REFRESH_MS = 60000;        // AUTO: återsänd alla tre register minst så ofta (som produktion)
const FORCED_POWER_REFRESH_MS = 2000;  // tvingade lägen: 40149 återsänds minst så ofta
const FORCED_MODE_REFRESH_MS = 10000;  // tvingade lägen: 40151/40016 (ändras sällan). Växelriktaren har 41193 = "Values maintained", ingen timeout
const POWER_DEADBAND_W = 100;     // skicka nytt 40149 bara vid ändring större än detta

// ---------- Indata ----------
const store = context;
const get = k => global.get(k);
const now = Date.now();
const warnings = [];

const isNum = v => typeof v === "number" && isFinite(v);
function numOrDefault(raw, def) {
    if (raw === undefined || raw === null || raw === "") return def;
    const n = Number(raw);
    return isNaN(n) ? def : n;
}
// färskt värde ur sma[key] = {v, ts}, eller null om det saknas/är gammalt
function fresh(key) {
    const o = (global.get("sma") || {})[key];
    if (!o || !isNum(o.v) || !isNum(o.ts) || now - o.ts > MAX_AGE_MS) return null;
    return o.v;
}

const socRaw = fresh("batSoc");
const currentSoC = (socRaw !== null && socRaw >= 0 && socRaw <= 100) ? Math.round(socRaw) : null;
const gridRaw = fresh("grid");
const grid_import = gridRaw !== null ? Math.round(gridRaw) : null;
const pvA = fresh("pvA");
const pvB = fresh("pvB");
const invAcW = fresh("invAc");
const batChgW = fresh("batChg");
const batDschW = fresh("batDsch");
const batNetW = fresh("batNet");
const batVol = fresh("batVol");
const phaseMaxA = fresh("phaseMax");

const targetSoC = Math.round(numOrDefault(get("sma_soc"), 50));
const forceZeroExport = parseInt(get("zero_export"), 10) || 0;
const pvPower = (pvA === null || pvB === null) ? 0 : Math.round(pvA) + Math.round(pvB);
const charge_power = Math.min(Math.round(numOrDefault(get("charge_power"), 5) * 1000), CHARGE_MAX_W);
const dischargePower = (val => val < DISCHARGE_MIN_W ? 0 : Math.min(val, INV_MAX_W))(parseInt(get("discharge"), 10) || 0);
const peakMqtt = parseInt(get("peak"), 10) || 0;
// Peak shaving är alltid på: sma/peak > 0 -> den nivån, annars GRID_MAX_W (13 kW). Gäller alla tillstånd.
const peakPower = peakMqtt > 0 ? peakMqtt : GRID_MAX_W;

// ---------- Validering (fail-safe) ----------
const missing = [];
if (currentSoC === null) missing.push("batSoc (30845)");
if (grid_import === null) missing.push("grid (30865)");
if (pvA === null || pvB === null) missing.push("pvA/pvB (30773/30961)");
if (invAcW === null) missing.push("invAc (30775)");
const failsafe = missing.length > 0;
if (batChgW === null || batDschW === null) warnings.push("batChg/batDsch saknas/gamla (31393/31395): fasgräns för laddning utan batteriavdrag");
if (phaseMaxA === null) warnings.push("phaseMax saknas/gammal (31435): ingen fasgräns i CHARGE");

const prev0 = store.get("state") || "AUTO";
// ---------- Husförbrukning ----------
// Växelriktarens AC-effekt (inkl. batteri) + nätnetto.
const housePower = failsafe ? 0 : Math.max(0, invAcW + grid_import);
const netGridImport = housePower - pvPower;
// Fasbaserad peak: nätmätarens fasström inkluderar redan batteriets bidrag. "Utan batteri" = uppmätt max-fas + batteriets
// urladdning (eller - laddning) fördelad på 3 faser. Batteriet ska ta det som ligger över triggern (säkring - marginal).
const phaseTrigA = PHASE_LIMIT_A - PHASE_MARGIN_A;
const phaseNoBatA = (phaseMaxA !== null && batNetW !== null) ? phaseMaxA + batNetW / (GRID_VOLT * 3) : null;
// Integrerande återkoppling mot uppmätt maxfas (som redan inkluderar batteriets hjälp), samma princip som effekt-peak.
const phaseFb = phaseMaxA !== null && batNetW !== null;
// Fasströmmen från 31435 är ett belopp (riktningen saknas). Vid nettoexport (grid_import < 0) räknas den som negativ, så att batteriet
// inte fortsätter urladda för att strömmen (nu i exportriktningen) ser hög ut.
const phaseEffA = phaseMaxA === null ? null : ((grid_import !== null && grid_import < 0) ? -phaseMaxA : phaseMaxA);
const phaseErrA = phaseFb ? phaseEffA - phaseTrigA : 0;
const phaseCmdPrev = store.get("phaseCmd");
const phaseWasActive = prev0 === "PEAK_SHAVING" && typeof phaseCmdPrev === "number";
let phaseBase = phaseWasActive ? phaseCmdPrev : (batNetW !== null ? Math.max(0, batNetW) : 0);
if (batNetW !== null) phaseBase = Math.min(phaseBase, Math.max(0, batNetW) + PHASE_MAX_LEAD_W);
// Fasström utan batteriets bidrag: vid laddning (batNetW < 0) är den lägre än den uppmätta. Fas-peak (urladdning) startar bara om
// lasten i sig ligger över gränsen; annars minskas laddningen via laddgränsen (byPhase) och batteriet fortsätter ladda med lägre effekt.
const phaseNoBatErrA = phaseFb ? phaseEffA + Math.min(batNetW, 0) / (GRID_VOLT * 3) - phaseTrigA : 0;
const phaseKickW = (phaseWasActive || phaseNoBatErrA <= 0) ? 0 : PHASE_KICK * phaseNoBatErrA * GRID_VOLT * 3;
const phaseCmdRaw = Math.round(phaseBase + phaseKickW + PHASE_GAIN * phaseErrA * GRID_VOLT * 3);
const phaseNeedW = phaseFb ? Math.max(0, phaseCmdRaw) : 0;
if (phaseMaxA !== null && batNetW === null) warnings.push("Fasbaserad peak av: batNet (31393/31395) saknas/gammal");
// Effektbaserad peak används bara när sma/peak är satt (effekttariff), eller som reserv om fasdata saknas.
// Utan sma/peak styr fasströmmen ensam (säkringen är den verkliga gränsen).
const peakSocBlocked = currentSoC !== null && (currentSoC < PEAK_MIN_SOC || (store.get("peakSocBlocked") === true && currentSoC < PEAK_MIN_SOC + PEAK_MIN_SOC_HYST));
store.set("peakSocBlocked", peakSocBlocked);
const powerTrigActive = (peakMqtt > 0 || phaseNoBatA === null) && !peakSocBlocked;
if (peakSocBlocked && (peakMqtt > 0 || phaseNoBatA === null) && netGridImport > peakPower) warnings.push(`Effekt-peak av: SoC ${currentSoC} % under golv ${PEAK_MIN_SOC} %`);
// Återkoppling: uppmätt batteri-nettoeffekt (+ urladdning) och uppmätt nätimport. Faller tillbaka på beräknat hus om batteridata saknas.
const peakFb = batNetW !== null && grid_import !== null;
// Integrerande återkoppling: bygger vidare på förra börvärdet (inte på uppmätt batterieffekt), så att batteriets faktiska
// verkningsgrad/offset inte ger kvarstående fel. Startar från uppmätt urladdning. Faller tillbaka på beräknat hus om batteridata saknas.
const peakCmdPrev = store.get("peakCmd");
let peakBase = (prev0 === "PEAK_SHAVING" && typeof peakCmdPrev === "number") ? peakCmdPrev : (batNetW !== null ? Math.max(0, batNetW) : 0);
if (batNetW !== null) peakBase = Math.min(peakBase, Math.max(0, batNetW) + PEAK_MAX_LEAD_W);
const powerNeedW = peakFb ? Math.round(peakBase + PEAK_GAIN * (grid_import - peakPower)) : Math.round(netGridImport - peakPower);
const powerTrig = powerTrigActive && (prev0 === "PEAK_SHAVING"
    ? (peakFb ? powerNeedW > PEAK_RELEASE_W : netGridImport > peakPower - PEAK_HYST_W)
    : (peakFb ? grid_import : netGridImport) > peakPower);
// Fas-peak startar först när startvillkoret gällt PHASE_CONFIRM_N körningar i följd och minst PHASE_CONFIRM_MS (enstaka felläsningar/spikar
// ska inte ge PEAK_SHAVING). Under väntan stryper CHARGE laddningen som vanligt. Redan aktiv fas-peak släpper som förut.
const phaseEnter = phaseFb && !phaseWasActive && phaseNoBatErrA > 0;
if (!phaseEnter) {
    store.set("phaseCnt", 0);
    store.set("phaseSince", undefined);
} else {
    if (typeof store.get("phaseSince") !== "number") store.set("phaseSince", now);
    store.set("phaseCnt", (store.get("phaseCnt") || 0) + 1);
}
const phaseCnt = store.get("phaseCnt") || 0;
const phaseConfirmed = phaseEnter && phaseCnt >= PHASE_CONFIRM_N && now - store.get("phaseSince") >= PHASE_CONFIRM_MS;
const phaseTrig = phaseFb && (phaseWasActive ? phaseCmdRaw > PHASE_RELEASE_W : phaseConfirmed);
const hasSolarSurplus = pvPower > (housePower + 50);
// Solöverskott med minne, så att läget inte hoppar mellan AUTO och LOCKED när solen ligger nära hus + 50 W
if (hasSolarSurplus) {
    store.set("lastSurplus", now);
    if (typeof store.get("surplusSince") !== "number") store.set("surplusSince", now);
} else {
    store.set("surplusSince", undefined);
}
const lastSurplus = store.get("lastSurplus");
const surplusSince = store.get("surplusSince");

if (dischargePower > 0 && currentSoC !== null && currentSoC <= targetSoC) warnings.push(`sma/discharge ${dischargePower} W ignoreras: SoC ${currentSoC} % <= mål ${targetSoC} %`);
// ---------- Tillståndsmaskin med hysteres ----------
const prev = prev0;
let cand;
if (failsafe) {
    cand = "FAILSAFE";
} else if (powerTrig || phaseTrig) {
    cand = "PEAK_SHAVING";
} else if (dischargePower > 0 && currentSoC > targetSoC) { // manuell urladdning stannar när SoC nått mål-SoC (sma/soc)
    cand = "DISCHARGE_MANUAL";
} else if (forceZeroExport === 1) {
    cand = "ZERO_EXPORT";
} else if (currentSoC < targetSoC - SOC_HYST || (prev === "CHARGE" && currentSoC < targetSoC)) {
    cand = "CHARGE";
} else if (currentSoC > targetSoC) {
    cand = "AUTO";
} else {
    const wantAuto = prev0 === "AUTO"
        ? (hasSolarSurplus || (typeof lastSurplus === "number" && now - lastSurplus < AUTO_HOLD_MS))
        : (hasSolarSurplus && typeof surplusSince === "number" && now - surplusSince >= AUTO_ENTER_MS);
    cand = (wantAuto && currentSoC < 100) ? "AUTO" : "LOCKED";
}
const lastChange = store.get("stateSince") || 0;
const bypassDwell = cand === "PEAK_SHAVING" || cand === "FAILSAFE" || prev === "FAILSAFE" || prev === "PEAK_SHAVING";
let currentState = cand;
if (cand !== prev && !bypassDwell && now - lastChange < MIN_DWELL_MS) {
    currentState = prev; // håll kvar tills minsta tid gått
    warnings.push(`Byte ${prev} -> ${cand} väntar (minsta tid ${MIN_DWELL_MS / 1000}s)`);
}
const stateChanged = currentState !== prev;
if (stateChanged) {
    store.set("state", currentState);
    store.set("stateSince", now);
    node.warn(`🔄 [v2] ${prev} -> ${currentState}`);
}

// AC-utgången är max INV_MAX_W totalt: PV + batteri <= 8000 W. Batterihjälpen kan inte bli större än det som blir kvar.
const dischargeCap = Math.max(0, Math.min(BAT_MAX_DISCHARGE_W, INV_MAX_W - pvPower));

// ---------- Parametrar per läge ----------
let mode = 803, powerLimit = 100, activePower = 0, reason = "", chargeCaps = null;
switch (currentState) {
    case "PEAK_SHAVING": {
        mode = 802;
        const byPower = powerTrigActive ? Math.min(Math.max(powerNeedW, 0), dischargeCap) : 0;
        store.set("peakCmd", byPower);
        // Fas-peak får inte skapa export: högst så mycket att nätimporten (uppmätt) blir noll.
        const noExportCapW = (batNetW !== null && grid_import !== null) ? Math.max(0, batNetW + grid_import) : dischargeCap;
        const phasePartW = phaseTrig ? Math.min(phaseNeedW, dischargeCap, noExportCapW) : 0;
        store.set("phaseCmd", phaseTrig ? phasePartW : undefined);
        const wanted = Math.max(byPower, phasePartW);
        activePower = Math.min(wanted, dischargeCap);
        if (wanted > dischargeCap) warnings.push(`Peak-hjälp begränsad till ${dischargeCap} W (AC-gräns ${INV_MAX_W} W minus PV ${pvPower} W); önskat ${wanted} W`);
        const cause = (powerTrig && phaseTrig) ? "effekt+fas" : phaseTrig ? "fas" : "effekt";
        reason = `Peak ${cause} (${powerTrigActive ? `max nät ${peakPower} W${peakMqtt > 0 ? "" : " reserv"}, ` : ""}fas ${phaseTrigA} A | bat ${activePower} W)`;
        break;
    }
    case "DISCHARGE_MANUAL": {
        mode = 802;
        activePower = Math.min(Math.max(dischargePower + housePower - pvPower, 0), dischargeCap);
        reason = `Mål-export ${dischargePower} W | bat ${activePower} W`;
        break;
    }
    case "ZERO_EXPORT": {
        mode = 802;
        activePower = Math.min(housePower, INV_MAX_W);
        powerLimit = Math.max(0, Math.min(Math.round(housePower / INV_MAX_W * 100), 100));
        reason = `Nollexport (${powerLimit}%)`;
        break;
    }
    case "CHARGE": {
        mode = 802;
        const byGrid = GRID_MAX_W - netGridImport;
        const byPeak = Math.max(peakPower - netGridImport, 0);
        // Nätladdning går via AC-anslutningen (max INV_MAX_W). Sol laddar direkt på DC och lägger ovanpå: max = 8000 + PV.
        const byAc = Math.min(BAT_MAX_CHARGE_W, INV_MAX_W + pvPower);
        // Fasgräns för laddning: integrerande laddgräns mot uppmätt maxfas. Snabb sänkning över gränsen, långsam höjning under.
        let byPhase = Infinity;
        if (phaseMaxA !== null) {
            const otherCaps = Math.min(byGrid, byAc, charge_power, byPeak);
            const capPrev = store.get("chargeCapCmd");
            let capBase = typeof capPrev === "number" ? capPrev : (batChgW !== null ? batChgW : otherCaps);
            if (batChgW !== null) capBase = Math.min(capBase, batChgW + PHASE_CHG_MAX_LEAD_W);
            const overA = phaseEffA - phaseTrigA;
            const k = overA > 0 ? PHASE_CHG_GAIN_DOWN : PHASE_CHG_GAIN_UP;
            byPhase = Math.max(0, Math.min(otherCaps, Math.round(capBase - k * overA * GRID_VOLT * 3)));
            store.set("chargeCapCmd", byPhase);
        }
        chargeCaps = { byAc, byGrid, byUser: charge_power, byPeak, byPhase: isFinite(byPhase) ? Math.round(byPhase) : null };
        const avail = Math.max(0, Math.round(Math.min(byGrid, byAc, charge_power, byPeak, byPhase)));
        activePower = -avail;
        reason = `Laddar (max ${avail} W)`;
        break;
    }
    case "LOCKED":
        mode = 802;
        reason = "Låst";
        break;
    case "FAILSAFE":
        reason = `FAILSAFE, saknar: ${missing.join(", ")}`;
        break;
    case "AUTO":
    default:
        reason = "Auto";
        break;
}

if (currentState !== "PEAK_SHAVING") { store.set("peakCmd", undefined); store.set("phaseCmd", undefined); }
if (currentState !== "CHARGE") store.set("chargeCapCmd", undefined);

// ---------- Format som Modbus (endast för visning i debug) ----------
const s32 = v => { const x = Math.round(v) | 0; return [(x >>> 16) & 0xFFFF, x & 0xFFFF]; };
const s16 = v => { const x = Math.round(v); return x < 0 ? 65536 + x : x; };
const desired = {
    "40151": { raw: [0, mode], txt: mode === 802 ? "802 aktiv" : "803 inaktiv" },
    "40016": { raw: [s16(powerLimit)], txt: `${powerLimit} %` },
    "40149": { raw: s32(activePower), txt: `${activePower} W` }
};

// ---------- Skicka-beslut (deadband/refresh) - ENDAST PLAN, inget skrivs ----------
const sent = store.get("sent") || {};
const wouldWrite = [];
const modeRefreshMs = currentState === "AUTO" ? REFRESH_MS : FORCED_MODE_REFRESH_MS;
const powerRefreshMs = currentState === "AUTO" ? REFRESH_MS : FORCED_POWER_REFRESH_MS;
function decide(reg, changed, age, refreshMs) {
    if (stateChanged || changed || age > refreshMs) {
        wouldWrite.push({ register: reg, value: desired[reg].raw, tolk: desired[reg].txt, orsak: stateChanged ? "lägesbyte" : changed ? "ändrat värde" : "refresh" });
        sent[reg] = { raw: desired[reg].raw, w: reg === "40149" ? activePower : null, ts: now };
    }
}
["40151", "40016"].forEach(reg => {
    const s = sent[reg];
    decide(reg, !s || JSON.stringify(s.raw) !== JSON.stringify(desired[reg].raw), s ? now - s.ts : Infinity, modeRefreshMs);
});
{
    const s = sent["40149"];
    const changed = !s || Math.abs(activePower - s.w) > POWER_DEADBAND_W;
    decide("40149", changed, s ? now - s.ts : Infinity, powerRefreshMs);
}
store.set("sent", sent);

// ---------- Status ----------
const color = { PEAK_SHAVING: "purple", DISCHARGE_MANUAL: "orange", ZERO_EXPORT: "red", CHARGE: "blue", LOCKED: "yellow", AUTO: "green", FAILSAFE: "red" }[currentState];
node.status({
    fill: color, shape: "dot",
    text: `[${currentState}] ${reason} | Hus: ${housePower}W | PV: ${pvPower}W | SoC ${currentSoC === null ? "?" : currentSoC}%→${targetSoC}% | Fas ${phaseMaxA === null ? "?" : phaseMaxA.toFixed(1)}A`
});

// ---------- Utgång 1: skicka till Modbus/MQTT (switch på address, 250 ms mellan meddelanden som produktion) ----------
if (wouldWrite.length === 0) return null;
/** @type {any[]} */
const toSend = wouldWrite.map(w => ({ payload: w.value, address: w.register, unique_id: "sma_" + w.register }));
if (stateChanged) {
    toSend.push({ payload: currentState, address: "MQTT_STATE", topic: "sma/state", unique_id: "sma_mqtt_state_update" });
}
toSend.forEach((m, i) => setTimeout(() => node.send([m, null]), i * 250));

// ---------- Utgång 2: debug-plan ----------
return [null, {
    topic: "sma/plan",
    payload: {
        state: currentState,
        prev_state: prev,
        reason,
        skickas: toSend.map(m => ({ address: m.address, payload: m.payload })),
        housePower,
        battery: { netto_w_direkt: batNetW, laddar_w: batChgW, urladdar_w: batDschW, spanning_v: batVol },
        phase: { max_a: phaseMaxA, utan_batteri_a: phaseNoBatA === null ? null : Math.round(phaseNoBatA * 100) / 100, trigger_a: phaseTrigA, behov_w: phaseNeedW, bekraftelser: phaseCnt },
        chargeCaps,
        dischargeCap,
        inputs: { powerTrigActive, targetSoC, currentSoC, pvPower, grid_import, invAcW, netGridImport, charge_power, peakPower, peakMqtt, dischargePower, forceZeroExport },
        warnings
    }
}];

const v = msg.payload;
global.set("zero_export", v);
node.status({fill: "blue", shape: "dot", text: `Nollexport: ${parseInt(v, 10) === 1 ? "på" : "av"}`});
return null;

// Register 30865-30868: Metering.GridMs.TotWIn / TotWOut (S32, W) -> nettoimport (+ import, - export)
// Skriver global "sma": grid
const p = msg.payload;
if (!Array.isArray(p) || p.length !== 4) {
    node.status({fill: "red", shape: "ring", text: "Väntar på 4 register"});
    return null;
}
const s32 = (h, l) => ((h << 16) | l) | 0;
const importPower = s32(p[0], p[1]);
const exportPower = s32(p[2], p[3]);
if (importPower === -2147483648 || exportPower === -2147483648) { // NaN -> uppdatera inte (blir gammalt -> FAILSAFE)
    node.status({fill: "yellow", shape: "ring", text: "NaN från mätaren"});
    return null;
}
let net = 0;
if (importPower > 0) net = importPower;
else if (exportPower > 0) net = exportPower * -1;
const s = global.get("sma") || {};
s.grid = {v: net, ts: Date.now()};
global.set("sma", s);
node.status({fill: net > 0 ? "yellow" : "green", shape: "dot", text: "Grid: " + net + " W"});
msg.payload = net;
return msg;

// Register 30773-30776: DcMs.Watt (PV A, S32) + GridMs.TotW (växelriktarens AC-effekt, S32) i en läsning
// Skriver global "sma": pvA, invAc
const p = msg.payload;
if (!Array.isArray(p) || p.length < 4) {
    node.status({fill: "red", shape: "ring", text: "Väntar på 4 register"});
    return null;
}
const s32 = (h, l) => ((h << 16) | l) | 0;
const NAN_S32 = -2147483648;
const pv = s32(p[0], p[1]);
const ac = s32(p[2], p[3]);
// NaN/negativt PV nattetid -> 0 (som produktion). AC-effekt NaN -> 0 (växelriktaren matar inte ut något).
const pvW = pv < 0 ? 0 : pv;
const acW = ac === NAN_S32 ? 0 : ac;
const s = global.get("sma") || {};
const ts = Date.now();
s.pvA = {v: pvW, ts};
s.invAc = {v: acW, ts};
global.set("sma", s);
node.status({fill: "green", shape: "dot", text: `PV A: ${pvW} W | AC: ${acW} W`});
msg.payload = {pv_a: pvW, inv_ac_w: acW};
return msg;

// Register 30961-30962: DcMs.Watt (PV B, S32)
// Skriver global "sma": pvB
if (Array.isArray(msg.payload) && msg.payload.length >= 2) {
    const val = ((msg.payload[0] << 16) | msg.payload[1]) | 0;
    // Nattens NaN/negativa spökvärden -> 0 (som produktion). Tidsstämpel sätts när läsningen lyckats.
    const s = global.get("sma") || {};
    s.pvB = {v: val < 0 ? 0 : val, ts: Date.now()};
    global.set("sma", s);
    node.status({fill: "green", shape: "dot", text: "PV B: " + (val < 0 ? 0 : val) + " W"});
}
return msg;

const v = msg.payload;
global.set("charge_power", v);
node.status({fill: "blue", shape: "dot", text: `Max laddning: ${v} kW`});
return null;

const v = msg.payload;
global.set("discharge", v);
node.status({fill: "blue", shape: "dot", text: `Urladdning: ${(parseInt(v, 10) || 0) >= 2500 ? Math.min(parseInt(v, 10), 8000) + " W (export)" : "av"}`});
return null;

const v = msg.payload;
global.set("peak", v);
node.status({fill: "blue", shape: "dot", text: `Peak: ${(parseInt(v, 10) || 0) > 0 ? parseInt(v, 10) + " W" : "av (fas-styrd)"}`});
return null;

// Register 31393-31396: BatChrg.CurBatCha (U32, W) + BatDsch.CurBatDsch (U32, W)
// Skriver global "sma": batChg, batDsch, batNet (+ urladdning, - laddning)
const p = msg.payload;
if (!Array.isArray(p) || p.length < 4) {
    node.status({fill: "red", shape: "ring", text: "Väntar på 4 register"});
    return null;
}
const u32 = (h, l) => ((h << 16) | l) >>> 0;
const NAN_U32 = 0xFFFFFFFF;
const chg = u32(p[0], p[1]);
const dsch = u32(p[2], p[3]);
if (chg === NAN_U32 || dsch === NAN_U32) {
    node.status({fill: "yellow", shape: "ring", text: "NaN från växelriktaren"});
    return null; // ts uppdateras inte -> värdet blir gammalt
}
const net = dsch - chg;
const s = global.get("sma") || {};
const ts = Date.now();
s.batChg = {v: chg, ts};
s.batDsch = {v: dsch, ts};
s.batNet = {v: net, ts};
global.set("sma", s);
node.status({fill: "green", shape: "dot", text: `Ladd ${chg} W | Urladd ${dsch} W | netto ${net} W`});
msg.payload = net;
return msg;

// Register 31435-31440: GridMs.A.phsA/B/C (S32 vardera, 0,001 A) - nätmätarens fasströmmar (belopp, riktning saknas)
// Skriver global "sma": phaseMax (högsta fasström, A), phaseA ([L1, L2, L3])
const p = msg.payload;
if (!Array.isArray(p) || p.length < 6) {
    node.status({fill: "red", shape: "ring", text: "Väntar på 6 register"});
    return null;
}
const amps = [0, 2, 4].map(i => {
    const v = ((p[i] << 16) | p[i + 1]) | 0;
    return v === -2147483648 ? null : Math.abs(v) / 1000;
});
const valid = amps.filter(a => a !== null);
if (valid.length === 0) {
    node.status({fill: "yellow", shape: "ring", text: "NaN från växelriktaren"});
    return null;
}
const max = Math.max(...valid);
const s = global.get("sma") || {};
const ts = Date.now();
s.phaseMax = {v: max, ts};
s.phaseA = {v: amps, ts};
global.set("sma", s);
const f = a => a === null ? "?" : a.toFixed(1);
node.status({fill: "green", shape: "dot", text: `L1 ${f(amps[0])} | L2 ${f(amps[1])} | L3 ${f(amps[2])} A | max ${max.toFixed(1)} A`});
msg.payload = max;
return msg;

// Skickar L1/L2/L3 (A, belopp) från global sma.phaseA till sma/fas/l1..l3 varje gång Fasström läst (1 s).
// Saknas en fas (NaN från växelriktaren) skickas inget för den - HA-sensorn blir då unavailable efter 5 s (expire_after).
const s = global.get("sma") || {};
const a = (s.phaseA || {}).v;
if (!Array.isArray(a)) return null;
const out = [];
["l1", "l2", "l3"].forEach((k, i) => {
    if (a[i] !== null && a[i] !== undefined) out.push({topic: "sma/fas/" + k, payload: a[i].toFixed(2)});
});
return [out];
